package io.github.jakediscord.hobbymod.astronomy;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
final class AstronomyTest {
 @Test void catalogIsDeterministicAndRecognizablePatternsStayFixed(){var a=new SkyCatalog(12);var b=new SkyCatalog(12);var c=new SkyCatalog(13);assertEquals(a.targets,b.targets);assertEquals(a.stars,b.stars);assertNotEquals(a.targets.get(29),c.targets.get(29));assertEquals(a.targets.subList(0,29),c.targets.subList(0,29));assertEquals(20,a.targets.stream().filter(SkyCatalog.Object::deep).count());assertEquals(49,a.targets.size());}
 @Test void directionsRemainUnitAndTimeCommandsAreStateless(){var a=new SkyCatalog(4);for(long time:new long[]{-240000,0,18000,24000,999999999})for(var o:a.targets){var d=o.direction(time);assertEquals(1,d.dot(d),1e-9);assertEquals(d,new SkyCatalog(4).target(o.id()).direction(time));}assertEquals(a.target(0).direction(18000).x(),a.target(0).direction(18000+32*24000).x(),1e-10);assertNotEquals(a.target(22).direction(18000),a.target(22).direction(42000));}
 @Test void everyConstellationCanBeObservedDuringTheSeasonalCycle(){var c=new SkyCatalog(4);for(var o:c.targets.subList(0,22)){boolean visible=false;for(int day=0;day<32;day++)if(o.direction(day*24000L+18000).y()>.3)visible=true;assertTrue(visible,o.name()+" must be observable at night in some season");}}
 @Test void exposureRequiresContinuousRealServerTime(){var e=new ObservationExposure();for(int t=0;t<=235;t+=5)assertFalse(e.advance(1,.7,t,18000+t));assertTrue(e.advance(1,.7,240,18240));assertFalse(e.advance(1,.7,245,6000));assertEquals(0,e.ticks);assertFalse(e.advance(2,.7,250,6005));assertFalse(e.advance(2,.1,255,6010));assertEquals(0,e.ticks);assertFalse(e.advance(2,.7,1000,6755));assertEquals(0,e.ticks);}
 @Test void frozenCelestialTimeStillAllowsRealExposure(){var e=new ObservationExposure();for(int t=0;t<=235;t+=5)assertFalse(e.advance(1,.7,t,18000));assertTrue(e.advance(1,.7,240,18000));}
 @Test void repeatedNightsRequiredAndBadOrForgedQualityRejected(){var j=new ObservationJournal();assertFalse(j.record(1,Double.NaN,18000,0));assertFalse(j.record(1,2,18000,0));assertFalse(j.record(49,1,18000,0));assertTrue(j.record(1,1,18000,0));assertFalse(j.record(1,1,18100,100));assertTrue(j.record(1,1,19000,1000));assertEquals(50,j.get(1).completeness);assertFalse(j.record(1,1,20000,2000));assertTrue(j.record(1,1,42000,3000));assertTrue(j.record(1,1,43000,4000));assertEquals(100,j.get(1).completeness);assertFalse(j.record(1,1,66000,5000));}
 @Test void weatherApertureFocusAndObstructionsHaveReadableEffects(){var cat=new SkyCatalog(14);double t=18000;var star=cat.targets.stream().filter(o->!o.deep() && o.direction(t).y()>.4).findFirst().orElseThrow();double good=SkyCatalog.quality(star,t,.72,8,80,0,0,true);assertTrue(good>.2);assertEquals(0,SkyCatalog.quality(star,t,.72,8,80,0,0,false));assertEquals(0,SkyCatalog.quality(star,t,.72,8,80,1,0,true));assertTrue(SkyCatalog.quality(star,t,.3,8,80,0,0,true)<good);var deep=cat.targets.stream().filter(o->o.deep() && o.direction(t).y()>.4).findFirst().orElseThrow();assertEquals(0,SkyCatalog.quality(deep,t,.72,8,35,0,0,true));assertTrue(SkyCatalog.quality(deep,t,.72,20,180,0,0,true)>SkyCatalog.quality(deep,t,.72,8,80,0,0,true));}
 @Test void meteorEventsAreRareBoundedAndSynchronized(){int days=0;for(int d=0;d<100;d++){boolean found=false;for(int t=14000;t<22000;t+=10){double p=SkyCatalog.meteor(42,d*24000L+t);assertEquals(p,SkyCatalog.meteor(42,d*24000L+t));if(p>=0){assertTrue(p<1);found=true;}}if(found)days++;}assertTrue(days>10 && days<40);}
}
